def test_logout_user_success(api_base_url, authorization_token):
    """
    Test the /user/logout endpoint for a successful operation.
    """
    headers = {
        "Authorization": f"Bearer {authorization_token}"
    }
    url = f"{api_base_url}user/logout"
    response = requests.get(url, headers=headers)

    assert response.status_code == 200, f"Expected 200 but got {response.status_code}"
    assert response.text.strip() == "", "Expected an empty response."


def test_logout_user_unauthorized(api_base_url):
    """
    Test the /user/logout endpoint with a missing or invalid token.
    """
    url = f"{api_base_url}user/logout"
    headers = {
        # Intentionally removing Authorization header
    }
    response = requests.get(url, headers=headers)

    assert response.status_code in [401, 403], f"Expected 401 or 403 but got {response.status_code}"
    assert "error" in response.text.lower(), "No error message in response."


